"package com.example.educationpath.di\n\nimport android.content.Context\nimport androidx.room.Room\nimport com.example.educationpath.data.AppDatabase\import com.example.educationpath.data.dao.PathDao\nimport com.example.educationpath.data.dao.StepDao\nimport dagger.Module\nimport dagger.Provides\import dagger.hilt.InstallIn\import dagger.hilt.android.qualifiers.ApplicationContext\import dagger.hilt.components.SingletonComponent\nimport javax.inject.Singleton\n\n@Module\n@InstallIn(SingletonComponent::class)\nobject DatabaseModule {\n\n    @Provides\n    @Singleton\n    fun provideDatabase(@ApplicationContext context: Context): AppDatabase {\n        return Room.databaseBuilder(context,\n                AppDatabase::class.java,\n                \"education_db\"\n            )\n            .build()\n    }\n\n    @Provides\n    @Singleton\n    fun pathDao(database: AppDatabase): PathDao = database.pathDao()\n\n    @Provides\n    @Singleton\n    fun stepDao(database: AppDatabase): StepDao = database.stepDao()\n}"